void PollServer::create_listen_socket(unsigned short port) {
  _listen_fd = socket(AF_INET, SOCK_STREAM, 0);
  if (_listen_fd < 0) {
    throw std::runtime_error(errno_message("socket(2) error"));
  }

  int yes = 1;
  if (setsockopt(_listen_fd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes)) < 0) {
    throw std::runtime_error(errno_message("setsockopt(SO_REUSEADDR) error"));
  }

  sockaddr_in address;
  std::memset(&address, 0, sizeof(address));
  address.sin_family = AF_INET;
  address.sin_addr.s_addr = htonl(INADDR_ANY);
  address.sin_port = htons(port);

  if (bind(_listen_fd, reinterpret_cast<sockaddr*>(&address), sizeof(address)) < 0) {
    throw std::runtime_error(errno_message("bind(2) error"));
  }
  if (listen(_listen_fd, SOMAXCONN) < 0) {
    throw std::runtime_error(errno_message("listen(2) error"));
  }
  set_nonblocking(_listen_fd);
}

