void PollServer::accept_clients() {
  while (true) {
    sockaddr_in client_address;
    socklen_t client_len = sizeof(client_address);
    int client_fd = accept(_listen_fd, reinterpret_cast<sockaddr*>(&client_address), &client_len);
    if (client_fd < 0) {
      if (would_block()) {
        break;
      }
      throw std::runtime_error(errno_message("accept(2) error"));
    }

    set_nonblocking(client_fd);
    Client client;
    client.fd = client_fd;
    client.output = "OK Подключение установлено. Отправьте: HELLO <имя>\n";
    _clients.push_back(client);
    std::cout << "> connected fd = " << client_fd << std::endl;
  }
}

