void PollServer::read_client(std::size_t index) {
  Client& client = _clients[index];
  char buffer[4096];
  while (true) {
    ssize_t count = recv(client.fd, buffer, sizeof(buffer), 0);
    if (count > 0) {
      client.input.append(buffer, static_cast<std::size_t>(count));
      if (client.input.size() > protocol::max_line_size) {
        client.output += protocol::response("ERR", "слишком длинная команда");
        close_client(index);
        return;
      }
      process_lines(index);
      if (index >= _clients.size()) {
        return;
      }
    } else if (count == 0) {
      close_client(index);
      return;
    } else {
      if (would_block()) {
        return;
      }
      close_client(index);
      return;
    }
  }
}

