void PollServer::write_client(std::size_t index) {
  Client& client = _clients[index];
  while (!client.output.empty()) {
    ssize_t count = send(client.fd, client.output.data(), client.output.size(), MSG_NOSIGNAL);
    if (count > 0) {
      client.output.erase(0u, static_cast<std::size_t>(count));
    } else if (count < 0 && would_block()) {
      return;
    } else {
      close_client(index);
      return;
    }
  }
}

