void PollServer::process_lines(std::size_t index) {
  Client& client = _clients[index];
  while (true) {
    std::size_t pos = client.input.find('\n');
    if (pos == std::string::npos) {
      break;
    }
    std::string line = client.input.substr(0u, pos);
    if (!line.empty() && line.back() == '\r') {
      line.pop_back();
    }
    client.input.erase(0u, pos + 1u);
    process_line(client, line);
  }
}

