void PollServer::process_line(Client& client, const std::string& line) {
  std::string text = protocol::trim(line);
  if (text.empty()) {
    client.output += protocol::response("ERR", "пустая строка протокола");
    return;
  }

  std::vector<std::string> words = protocol::split_words(text);
  if (words.empty()) {
    client.output += protocol::response("ERR", "пустая строка протокола");
    return;
  }

  if (!client.authorized) {
    if (words[0] != "HELLO" || words.size() != 2u) {
      client.output += protocol::response("ERR", "сначала отправьте HELLO <имя>");
      return;
    }

    try {
      _model.variables(words[1]);
      client.user = words[1];
      client.authorized = true;
      client.output += protocol::response("OK", "пользователь " + client.user + " подключён");
    } catch (const CalculatorError& error) {
      client.output += protocol::response("ERR", error.what());
    }
    return;
  }

  const std::string& verb = words[0];

  if (verb == "QUIT") {
    client.output += protocol::response("OK", "до свидания");
    return;
  }

  if (verb == "PERF") {
    client.output += protocol::response("OK", "PERF");
    return;
  }

  if (verb != "CMD") {
    client.output += protocol::response("ERR", "неизвестный тип сообщения");
    return;
  }

  std::string command = protocol::trim(text.substr(3u));

  try {
    std::string result = _model.execute(client.user, command);
    client.output += protocol::response("OK", result);
  } catch (const CalculatorError& error) {
    client.output += protocol::response("ERR", std::string("Ошибка: ") + error.what());
  } catch (const std::exception& error) {
    client.output += protocol::response("ERR", std::string("Внутренняя ошибка: ") + error.what());
  }
}

