void PollServer::rebuild_events() {
  _poll_fds.clear();

  pollfd listener;
  listener.fd = _listen_fd;
  listener.events = POLLIN;
  listener.revents = 0;
  _poll_fds.push_back(listener);

  for (const Client& client : _clients) {
    pollfd item;
    item.fd = client.fd;
    item.events = POLLIN;
    if (!client.output.empty()) {
      item.events |= POLLOUT;
    }
    item.revents = 0;
    _poll_fds.push_back(item);
  }
}

