void ConsoleClient::send_line(const std::string& line) {
  std::size_t sent = 0u;
  while (sent < line.size()) {
    ssize_t count = send(_socket, line.data() + sent, line.size() - sent, 0);
    if (count < 0) {
      throw std::runtime_error(errno_message("send(2) error"));
    }
    if (count == 0) {
      throw std::runtime_error("соединение закрыто при отправке");
    }
    sent += static_cast<std::size_t>(count);
  }
}

