std::string ConsoleClient::receive_line() {
  std::string line;
  char c = 0;
  while (true) {
    ssize_t count = recv(_socket, &c, 1u, 0);
    if (count < 0) {
      throw std::runtime_error(errno_message("recv(2) error"));
    }
    if (count == 0) {
      throw std::runtime_error("соединение закрыто сервером");
    }
    if (c == '\n') {
      break;
    }
    if (c != '\r') {
      line.push_back(c);
    }
    if (line.size() > protocol::max_line_size) {
      throw std::runtime_error("слишком длинный ответ сервера");
    }
  }
  return line;
}

