/*! @file protocol.cpp
Исходный файл вспомогательных функций прикладного протокола. */

#include "common/protocol.hpp"

#include <algorithm>
#include <cctype>
#include <sstream>

namespace protocol {

std::string trim(const std::string& s) {
  std::size_t first = 0u;
  while (first < s.size() && std::isspace(static_cast<unsigned char>(s[first]))) {
    ++first;
  }
  std::size_t last = s.size();
  while (last > first && std::isspace(static_cast<unsigned char>(s[last - 1u]))) {
    --last;
  }
  return s.substr(first, last - first);
}

std::vector<std::string> split_words(const std::string& s) {
  std::istringstream input(s);
  std::vector<std::string> result;
  std::string word;
  while (input >> word) {
    result.push_back(word);
  }
  return result;
}

std::string one_line(std::string s) {
  std::replace(s.begin(), s.end(), '\n', ' ');
  std::replace(s.begin(), s.end(), '\r', ' ');
  return s;
}

std::string response(const std::string& status, const std::string& text) {
  return status + " " + one_line(text) + "\n";
}

bool starts_with(const std::string& s, const std::string& prefix) {
  return s.size() >= prefix.size() && std::equal(prefix.begin(), prefix.end(), s.begin());
}

} // namespace protocol

