class ExpressionParser {
public:

  ExpressionParser(const std::string& input, Variables variables) : _input(input), _variables(variables), _pos(0u) {}

  long long parse() {
    long long value = parse_expression();
    skip_spaces();
    if (_pos != _input.size()) {
      throw CalculatorError("лишние символы в выражении");
    }
    return value;
  }

private:

  long long parse_expression() {
    long long value = parse_term();
    while (true) {
      skip_spaces();
      if (match('+')) {
        value += parse_term();
      } else if (match('-')) {
        value -= parse_term();
      } else {
        break;
      }
    }
    return value;
  }

  long long parse_term() {
    long long value = parse_factor();
    while (true) {
      skip_spaces();
      if (match('*')) {
        value *= parse_factor();
      } else if (match('/')) {
        long long divisor = parse_factor();
        if (divisor == 0) {
          throw CalculatorError("деление на ноль");
        }
        value /= divisor;
      } else {
        break;
      }
    }
    return value;
  }

  long long parse_factor() {
    skip_spaces();
    if (_pos >= _input.size()) {
      throw CalculatorError("ожидалось число, переменная или скобка");
    }

    if (match('+')) {
      return parse_factor();
    }
    if (match('-')) {
      return -parse_factor();
    }
    if (match('(')) {
      long long value = parse_expression();
      skip_spaces();
      if (!match(')')) {
        throw CalculatorError("не закрыта скобка");
      }
      return value;
    }

    char c = _input[_pos];
    if (c == 'X' || c == 'x') {
      ++_pos;
      return _variables.x;
    }
    if (c == 'Y' || c == 'y') {
      ++_pos;
      return _variables.y;
    }
    if (c == 'Z' || c == 'z') {
      ++_pos;
      return _variables.z;
    }
    if (std::isdigit(static_cast<unsigned char>(c))) {
      return parse_integer();
    }

    throw CalculatorError("недопустимый символ в выражении");
  }

  long long parse_integer() {
    skip_spaces();
    long long value = 0;
    bool has_digit = false;
    while (_pos < _input.size() && std::isdigit(static_cast<unsigned char>(_input[_pos]))) {
      has_digit = true;
      value = value * 10 + static_cast<long long>(_input[_pos] - '0');
      ++_pos;
    }
    if (!has_digit) {
      throw CalculatorError("ожидалось целое число");
    }
    return value;
  }

  bool match(char expected) {
    if (_pos < _input.size() && _input[_pos] == expected) {
      ++_pos;
      return true;
    }
    return false;
  }

  void skip_spaces() {
    while (_pos < _input.size() && std::isspace(static_cast<unsigned char>(_input[_pos]))) {
      ++_pos;
    }
  }

  const std::string& _input;
  Variables _variables;
  std::size_t _pos;
};

