void ConsoleClient::run() {
  std::cout << "> Сетевой калькулятор. Пользователь: " << _user << std::endl;
  print_help();

  while (true) {
    std::cout << (_performance_mode ? "perf> " : "calc> ");
    std::cout.flush();

    std::string command;
    if (!std::getline(std::cin, command)) {
      break;
    }
    command = protocol::trim(command);
    if (command.empty()) {
      continue;
    }

    if (command == "помощь" || command == "help") {
      print_help();
      continue;
    }
    if (command == "история" || command == "history") {
      print_history();
      continue;
    }
    if (command == ":perf on") {
      _performance_mode = true;
      std::cout << "> режим тестирования производительности включён" << std::endl;
      continue;
    }
    if (command == ":perf off") {
      _performance_mode = false;
      std::cout << "> режим тестирования производительности выключен" << std::endl;
      continue;
    }
    if (command == "выход" || command == "quit" || command == "exit") {
      std::string answer = request("QUIT\n");
      std::cout << "< " << answer << std::endl;
      break;
    }

    _history.push_back(command);
    std::string packet;
    if (_performance_mode) {
      packet = "PERF " + protocol::one_line(command) + "\n";
    } else {
      packet = "CMD " + protocol::one_line(command) + "\n";
    }

    try {
      std::string answer = request(packet);
      std::cout << "< " << answer << std::endl;
    } catch (const std::exception& error) {
      std::cerr << "client error: " << error.what() << std::endl;
      break;
    }
  }
}
